"""One-time exact-base source patch transport. Removed before merging the PR.
The payload is data: offset replacements with before/after SHA-256 checks.
Only the eight named vocabulary files can be changed. Nothing is executed.
"""
import base64, hashlib, json, pathlib, zlib
encoded = ''''''
allowed = {'dopa-word/'+name for name in ('app.mjs','model.mjs','index.html','word.css','README.md','CATEGORIES.md','tests/browser.py','tests/categories_browser.py')}
patches = json.loads(zlib.decompress(base64.b64decode(encoded)))
assert {p['path'] for p in patches} == allowed
ready=[]
for item in patches:
    path=pathlib.Path(item['path'])
    assert path.is_file() and not path.is_symlink()
    before=path.read_bytes()
    assert hashlib.sha256(before).hexdigest()==item['before'], 'Base mismatch: '+str(path)
    source=before.decode('utf8')
    for start,end,replacement in reversed(item['ops']):
        assert isinstance(start,int) and isinstance(end,int) and 0<=start<=end<=len(source)
        source=source[:start]+replacement+source[end:]
    after=source.encode('utf8')
    assert hashlib.sha256(after).hexdigest()==item['after'], 'Result mismatch: '+str(path)
    ready.append((path,after))
for path,data in ready:
    path.write_bytes(data)
    print('Applied',path,hashlib.sha256(data).hexdigest())
